def get_map_cmd_for(trx, first_ant_num=1, last_ant_num=8):
    """
    Generate tx or rx map command

    :param trx: 'tx' or 'rx' str
    :param first_ant_num: default 1 int
    :param last_ant_num: default 8 int
    :return: full command
    :rtype: str
    """
    cmd_a = [
        "/ action create AntennaPath /ant{num}_hran_radio /rf/ant{num}".format(num=num)
        for num in range(first_ant_num, last_ant_num + 1)
    ]
    cmd_b = [
        "/ant{num}_hran_radio get {trx}_carrier_ids".format(num=num, trx=trx)
        for num in range(first_ant_num, last_ant_num + 1)
    ]
    return "\n".join(cmd_a + cmd_b)


def get_trx_power_command(tx_map):
    """
    Generate tx power command

    :param tx_map: dict mapped txs (key:tx id, value: antenna)
    :return: full command
    :rtype: str
    """
    cmd = [
        '{antenna} action measure_power "{tx_id}"'.format(antenna=antenna, tx_id=tx)
        for tx, antenna in tx_map.items()
    ]
    return "\n".join(cmd)


def get_trx_carrier_command(trx_map):
    """
    Generate tx or rx  carrier command

    :param trx_map: dict mapped trxs (key:trx id, value: antenna)
    :return: full command
    :rtype: str
    """
    cmd = [
        '{antenna} action read_config "{trx_id}"'.format(antenna=antenna, trx_id=trx)
        for trx, antenna in trx_map.items()
    ]
    return "\n".join(cmd)


def get_rx_lna_device_command(num_antenna=8):
    """
    Get rx lna map

    :param num_antenna: default 8
    :return: str command
    """
    cmd_a = [
        "/ action create AntennaPath /ant{num}_hran_radio /rf/ant{num}".format(num=num)
        for num in range(1, num_antenna + 1)
    ]
    cmd_b = [
        "/ action create LnaDevice /lna{num} /rf/rx{num}".format(num=num)
        for num in range(1, num_antenna + 1)
    ]
    return "\n".join(cmd_a + cmd_b)


def get_rx_max_gain_command(rx, lna_map):
    """
    Get rx map command

    :param rx:
    :param lna_map: lna map
    :return: str command
    """
    return "/{} get gain_target".format(lna_map[int(rx)])
